Card::Card(const QString &title, const QString &description, const QString date, QString priority, Tableau *tableau, QWidget *parent)
    : QWidget(parent), m_tags(QStringList()), parentTableau(tableau), m_estimatedTime(0), m_spentTime(0)
{
    this->setMouseTracking(true);
    m_title = title;
    m_description = description;
    m_date = date;
    m_priority = priority;
    setMinimumHeight(120);
    setAcceptDrops(true);

    QVBoxLayout *mainVerticalLayout = new QVBoxLayout(this);
    mainVerticalLayout->setContentsMargins(10, 8, 10, 8);
    mainVerticalLayout->setSpacing(6);


    QHBoxLayout *topLayout = new QHBoxLayout();
    topLayout->setSpacing(10);


    if (priority == "Élevée")
    {
        titleLabel->setStyleSheet("background-color: #ffe6e6; border: 1px solid #ff6666; padding: 8px; border-radius: 4px;");
    }
    else if (priority == "Moyenne")
    {
        titleLabel->setStyleSheet("background-color: #fff3cd; border: 1px solid #ffc107; padding: 8px; border-radius: 4px;");
    }
    else
    {
        titleLabel->setStyleSheet("background-color: #d4edda; border: 1px solid #28a745; padding: 8px; border-radius: 4px;");
    }

    titleLabel->setWordWrap(true);
    QString completed_task = m_title + "\n" + m_description + "\n" + m_date;
    titleLabel->setText(completed_task);

    // Checkbox
    checkbox->setStyleSheet(
        "QCheckBox {"
        "    spacing: 6px;"
        "    background-color: transparent;"
        "}"
        "QCheckBox::indicator {"
        "    width: 16px;"
        "    height: 16px;"
        "    border-radius: 8px;"
        "    border: 2px solid #C8E6C9;"
        "    background-color: transparent;"
        "}"
        "QCheckBox::indicator:hover {"
        "    border: 2px solid #4CAF50;"
        "    background-color: rgba(76,175,80,0.15);"
        "}"
        "QCheckBox::indicator:checked {"
        "    background-color: #4CAF50;"
        "    border: 2px solid #4CAF50;"
        "    image: url(:/check_small_18dp_FFFFFF_FILL0_wght400_GRAD0_opsz20.svg);"
        "}"
        "QCheckBox::indicator:checked:hover {"
        "    background-color: #43A047;"
        "    border: 2px solid #43A047;"
        "}");
    checkbox->setAttribute(Qt::WA_StyledBackground, true);
    checkbox->setAutoFillBackground(false);

    // Boutons
    btn_modifier->setIcon(QIcon(":/edit_18dp_1F1F1F_FILL0_wght400_GRAD0_opsz20.svg"));
    btn_modifier->setFixedSize(25, 25);
    btn_modifier->setStyleSheet(
        "QPushButton {"
        "    border: none;"
        "    background-color: transparent;"
        "}"
        "QPushButton:hover {"
        "    background-color: #e9ecef;"
        "    border-radius: 3px;"
        "}");

    btn_delete->setIcon(QIcon(":/close_18dp_1F1F1F_FILL0_wght400_GRAD0_opsz20.svg"));
    btn_delete->setFixedSize(25, 25);
    btn_delete->setStyleSheet(
        "QPushButton {"
        "    border: none;"
        "    background-color: transparent;"
        "}"
        "QPushButton:hover {"
        "    background-color: #ffe6e6;"
        "    border-radius: 3px;"
        "}");

    topLayout->addWidget(checkbox);
    topLayout->addWidget(titleLabel, 1);
    topLayout->addWidget(btn_modifier);
    topLayout->addWidget(btn_delete);

    createTagsDisplay();
    createTimeDisplay();

    mainVerticalLayout->addLayout(topLayout);
    mainVerticalLayout->addWidget(tagsContainer);
    mainVerticalLayout->addWidget(timeContainer);


    connect(btn_delete, SIGNAL(clicked()), this, SLOT(on_btn_delete_clicked()));
    connect(btn_modifier, SIGNAL(clicked()), this, SLOT(on_btn_modifier_clicked()));
    connect(checkbox, SIGNAL(stateChanged(int)), this, SLOT(on_checkbox_stateChanged(int)));
}


