void Card::mousePressEvent(QMouseEvent *event)
{
    if (event->button() == Qt::LeftButton)
    {
        dragStartPosition = event->pos();
    }
    QWidget::mousePressEvent(event);
}

void Card::mouseMoveEvent(QMouseEvent *event)
{
    if (!(event->buttons() & Qt::LeftButton))
    {
        return;
    }


    if ((event->pos() - dragStartPosition).manhattanLength() < QApplication::startDragDistance())
    {
        return;
    }

    qDebug() << "ðŸš€ DÃ©but du drag pour carte ID:" << cardId << "Titre:" << m_title;

    // CrÃ©er le drag
    QDrag *drag = new QDrag(this);
    QMimeData *mimeData = new QMimeData;

    // âœ… IMPORTANT: Stocker l'ID correctement
    mimeData->setText(QString::number(cardId));
    mimeData->setData("application/x-card", QByteArray::number(cardId));

    drag->setMimeData(mimeData);

    // DÃ©finir le pixmap (image pendant le drag)
    QPixmap pixmap(this->size());
    this->render(&pixmap);
    drag->setPixmap(pixmap);
    drag->setHotSpot(event->pos());

    // Changer l'apparence pendant le drag
    this->setStyleSheet("background-color: #e0e0e0; border: 2px  #666;");

    qDebug() << "ðŸ“¦ Mime data prÃ©parÃ©e avec ID:" << cardId;

    // ExÃ©cuter le drag
    Qt::DropAction dropAction = drag->exec(Qt::MoveAction);

    qDebug() << "ðŸŽ¯ Drag terminÃ© avec action:" << dropAction;

    // Restaurer l'apparence
    if (dropAction != Qt::MoveAction)
    {
        // Drag annulÃ©, restaurer l'apparence normale
        updateCardStyle();
    }
}

// Ajoutez aussi cette mÃ©thode pour restaurer le style
void Card::updateCardStyle()
{
    if (m_priority == "Élevée")
    {
        titleLabel->setStyleSheet("background-color: #ffe6e6; border: 1px solid #ff6666;");
    }
    else if (m_priority == "Moyenne")
    {
        titleLabel->setStyleSheet("background-color: #fff3cd; border: 1px solid #ffc107;");
    }
    else
    { // Faible
        titleLabel->setStyleSheet("background-color: #d4edda; border: 1px solid #28a745;");
    }
}

void Card::on_checkbox_stateChanged(int state)
{


    if (!parentTableau)
    {
        qDebug() << "âŒ Pas de Tableau parent";
        return;
    }

    if (state == Qt::Checked)
    {

        qDebug() << "ðŸ“¦ DÃ©placement automatique vers FINISHED";
        parentTableau->deplacerCarteVersFinished(this);
    }
    else
    {

        int carte_id = getCardId();
        if (carte_id != -1 && parentTableau->db && parentTableau->db->isOpen())
        {
            QSqlQuery update(*(parentTableau->db));
            update.prepare("UPDATE Cartes SET terminee = 0 WHERE id_carte = :id_carte");
            update.bindValue(":id_carte", carte_id);
            update.exec();
            qDebug() << "ðŸ“ Carte marquÃ©e comme non terminÃ©e";
        }
    }
}

void Card::createTagsDisplay()
{
    tagsContainer = new QWidget(this);
    tagsLayout = new QHBoxLayout(tagsContainer);
    tagsLayout->setSpacing(5);
    tagsLayout->setContentsMargins(0, 0, 0, 0);
    tagsLayout->setAlignment(Qt::AlignLeft);

    updateTagsDisplay();


    if (m_tags.isEmpty())
    {
        tagsContainer->setVisible(false);
    }
}

void Card::updateTagsDisplay()
{
    // Nettoyer les anciens tags
    QLayoutItem *item;
    while ((item = tagsLayout->takeAt(0)) != nullptr)
    {
        if (item->widget())
        {
            delete item->widget();
        }
        delete item;
    }


    QStringList colors = {"#3498db", "#e74c3c", "#2ecc71", "#f39c12",
                          "#9b59b6", "#1abc9c", "#e67e22", "#34495e"};


    int colorIndex = 0;
    for (const QString &tag : m_tags)
    {
        QFrame *tagFrame = new QFrame();
        tagFrame->setStyleSheet(
            QString("QFrame {"
                    "   background-color: %1;"
                    "   border-radius: 8px;"
                    "   padding: 3px 8px;"
                    "}")
                .arg(colors[colorIndex % colors.size()]));

        QHBoxLayout *tagFrameLayout = new QHBoxLayout(tagFrame);
        tagFrameLayout->setContentsMargins(4, 2, 4, 2);
        tagFrameLayout->setSpacing(0);

        QLabel *tagLabel = new QLabel(tag);
        tagLabel->setStyleSheet(
            "color: white;"
            "font-size: 11px;"
            "font-weight: bold;"
            "background: transparent;");

        tagFrameLayout->addWidget(tagLabel);
        tagsLayout->addWidget(tagFrame);

        colorIndex++;
    }

    tagsContainer->setVisible(!m_tags.isEmpty());
}

QStringList Card::getTags() const
{
    return m_tags;
}

void Card::setTags(const QStringList &tags)
{
    m_tags = tags;
    updateTagsDisplay();
}

