void Card::retranslate(TranslationManager *tm)
{
    if (!tm)
        return;

    // Traduire les prioritÃ©s
    QString priority = getPriority();
    if (priority == "Élevée" || priority == "High")
    {
        setPriority(tm->translate("Élevée"));
    }
    else if (priority == "Moyenne" || priority == "Medium")
    {
        setPriority(tm->translate("Moyenne"));
    }
    else if (priority == "Faible" || priority == "Low")
    {
        setPriority(tm->translate("Faible"));
    }

    // Mettre Ã  jour le style en fonction de la prioritÃ© traduite
    updateCardStyle();
}
