void Card::createTimeDisplay()
{
    timeContainer = new QWidget(this);
    QHBoxLayout *timeLayout = new QHBoxLayout(timeContainer);
    timeLayout->setSpacing(8);
    timeLayout->setContentsMargins(0, 4, 0, 0);
    timeLayout->setAlignment(Qt::AlignLeft);

    // Label avec icône
    timeLabel = new QLabel();
    timeLabel->setStyleSheet(
        "font-size: 11px;"
        "color: #6c757d;"
        "background: transparent;"
        "padding: 2px 6px;");

    // Barre de progression compacte
    timeProgressBar = new QProgressBar();
    timeProgressBar->setMinimum(0);
    timeProgressBar->setMaximum(100);
    timeProgressBar->setValue(0);
    timeProgressBar->setFixedHeight(8);
    timeProgressBar->setFixedWidth(80);
    timeProgressBar->setTextVisible(false);
    timeProgressBar->setStyleSheet(
        "QProgressBar {"
        "   border: 1px solid #e0e0e0;"
        "   border-radius: 4px;"
        "   background-color: #f8f9fa;"
        "}"
        "QProgressBar::chunk {"
        "   background: qlineargradient(x1:0, y1:0, x2:1, y2:0, "
        "       stop:0 #667eea, stop:1 #764ba2);"
        "   border-radius: 3px;"
        "}");

    timeLayout->addWidget(timeLabel);
    timeLayout->addWidget(timeProgressBar);
    timeLayout->addStretch();

    updateTimeDisplay();

    // Masquer si pas de temps défini
    if (m_estimatedTime == 0)
    {
        timeContainer->setVisible(false);
    }
}

void Card::updateTimeDisplay()
{
    if (m_estimatedTime == 0)
    {
        timeContainer->setVisible(false);
        return;
    }

    timeContainer->setVisible(true);

    // Texte avec icône horloge
    timeLabel->setText(QString("⏱️ %1h / %2h")
                           .arg(m_spentTime)
                           .arg(m_estimatedTime));

    // Calcul du pourcentage
    int percentage = (m_spentTime * 100) / m_estimatedTime;
    if (percentage > 100)
        percentage = 100;

    timeProgressBar->setValue(percentage);

    // Couleur selon progression
    QString color;
    if (percentage >= 100)
    {
        color = "stop:0 #e74c3c, stop:1 #c0392b"; // Rouge (dépassé)
    }
    else if (percentage >= 80)
    {
        color = "stop:0 #f39c12, stop:1 #e67e22"; // Orange (attention)
    }
    else if (percentage >= 50)
    {
        color = "stop:0 #3498db, stop:1 #2980b9"; // Bleu
    }
    else
    {
        color = "stop:0 #2ecc71, stop:1 #27ae60"; // Vert (bon)
    }

    timeProgressBar->setStyleSheet(
        QString("QProgressBar {"
                "   border: 1px solid #e0e0e0;"
                "   border-radius: 4px;"
                "   background-color: #f8f9fa;"
                "}"
                "QProgressBar::chunk {"
                "   background: qlineargradient(x1:0, y1:0, x2:1, y2:0, %1);"
                "   border-radius: 3px;"
                "}")
            .arg(color));
}

void Card::setEstimatedTime(int hours)
{
    m_estimatedTime = hours;
    updateTimeDisplay();
}

