card_dialog::card_dialog(QWidget *parent) :
    QDialog(parent),
    ui(new Ui::card_dialog)
{
    ui->setupUi(this);
    button_group->setExclusive(true);
    button_group->addButton(ui->checkLow);
    button_group->addButton(ui->checkMedium);
    button_group->addButton(ui->checkHigh);
    ui->checkMedium->setChecked(true);

    // ========== TAGS WIDGET ==========
    tagsWidget = new TagsWidget(this);
    QVBoxLayout *tagsLayout = new QVBoxLayout(ui->tagsWidgetContainer);
    tagsLayout->setContentsMargins(0, 0, 0, 0);
    tagsLayout->addWidget(tagsWidget);

    // ========== TIME WIDGET ==========
    timeWidget = new TimeWidget(this);
    QVBoxLayout *timeLayout = new QVBoxLayout(ui->timeWidgetContainer);
    timeLayout->setContentsMargins(0, 0, 0, 0);
    timeLayout->addWidget(timeWidget);

    TranslationManager* translationManager = TranslationManager::instance();
    translationManager->registerWidget(this);
    ui->checkLow->setText(translationManager->translate("Faible"));
    ui->checkMedium->setText(translationManager->translate("Moyenne"));
    ui->checkHigh->setText(translationManager->translate("Élevée"));
    taskPriority = translationManager->translate("Moyenne");
}

card_dialog::~card_dialog()
{
    delete ui;
}

QString card_dialog::getPriority(){
    if (ui->checkHigh->isChecked()) return "Élevée";
    if (ui->checkMedium->isChecked()) return "Moyenne";
    if (ui->checkLow->isChecked()) return "Faible";
    return "";
}

void card_dialog::on_buttonBox_accepted()
{
    taskName = ui->tasklineEdit->text();
    taskDescription = ui->descriptionlineEdit->text();
    taskDate = ui->calendarWidget->selectedDate();
    taskPriority = card_dialog::getPriority();
    taskTags = tagsWidget->getSelectedTags();
    taskEstimatedTime = timeWidget->getEstimatedTime();
    taskSpentTime = timeWidget->getSpentTime();

    ui->tasklineEdit->clear();
    ui->descriptionlineEdit->clear();
}

void card_dialog::setDialogText(QString text){
    ui->tasklineEdit->setText(text);
}

void card_dialog::setDialogDescription(QString description){
    ui->descriptionlineEdit->setText(description);
}

void card_dialog::setDialogTags(const QStringList &tags)
{
    tagsWidget->setSelectedTags(tags);
}

void card_dialog::setDialogTime(int estimated, int spent)
{
    timeWidget->setEstimatedTime(estimated);
    timeWidget->setSpentTime(spent);
}

void card_dialog::retranslateUi()
{
    TranslationManager* translationManager = TranslationManager::instance();

    ui->label->setText(translationManager->translate("Nom de la carte"));
    ui->label_2->setText(translationManager->translate("Priorité"));
    ui->checkLow->setText(translationManager->translate("Faible"));
    ui->checkMedium->setText(translationManager->translate("Moyenne"));
    ui->checkHigh->setText(translationManager->translate("Élevée"));

    ui->buttonBox->button(QDialogButtonBox::Ok)->setText(translationManager->translate("OK"));
    ui->buttonBox->button(QDialogButtonBox::Cancel)->setText(translationManager->translate("Annuler"));

    QString currentPriority = getPriority();
    if (!currentPriority.isEmpty()) {
        taskPriority = translationManager->translate(currentPriority);
    }
}

