void HomePage::creerInterface()
{
    mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(40, 40, 40, 40);
    mainLayout->setSpacing(30);

    // ========== EN-TÊTE ==========
    QLabel *titre = new QLabel("Mes Projets");
    titre->setStyleSheet(
        "font-size: 32px;"
        "font-weight: bold;"
        "color: #2c3e50;"
    );

    QLabel *sousTitre = new QLabel("Sélectionnez un projet pour commencer ou créez-en un nouveau");
    sousTitre->setStyleSheet(
        "font-size: 14px;"
        "color: #7f8c8d;"
        "margin-bottom: 10px;"
    );

    mainLayout->addWidget(titre);
    mainLayout->addWidget(sousTitre);

    // ========== BOUTON NEW PROJECT ==========
    QPushButton *btnNewProject = new QPushButton("➕ Nouveau Projet");
    btnNewProject->setMinimumHeight(60);
    btnNewProject->setMaximumWidth(300);
    btnNewProject->setCursor(Qt::PointingHandCursor);
    btnNewProject->setStyleSheet(
        "QPushButton {"
        "   background: qlineargradient(x1:0, y1:0, x2:1, y2:0, "
        "       stop:0 #3498db, stop:1 #2980b9);"
        "   color: white;"
        "   border: none;"
        "   border-radius: 10px;"
        "   font-size: 16px;"
        "   font-weight: bold;"
        "   padding: 15px 30px;"
