void HomePage::chargerProjets()
{
    db->open();
    if (!db || !db->isOpen()) {
        qDebug() << "❌ Base de données non disponible";
        return;
    }

    qDebug() << "🔄 Chargement des projets sur la page d'accueil...";

    // Nettoyer les projets existants (sauf le stretch)
    QLayoutItem *item;
    while ((item = projectsLayout->takeAt(0)) != nullptr) {
        if (item->widget()) {
            delete item->widget();
        }
        delete item;
    }

    // Requête SQL
    QSqlQuery req(*db);
    req.prepare("SELECT id_projet, nom_projet, date_creation FROM Projets ORDER BY date_creation DESC");

    if (!req.exec()) {
        QMessageBox::warning(this, "Erreur", "Impossible de charger les projets");
        return;
    }

    int count = 0;
    while (req.next()) {
        int id = req.value(0).toInt();
        QString nom = req.value(1).toString();
        QString date = req.value(2).toString();

        creerCarteProjet(id, nom, date);
        count++;
    }

    projectsLayout->addStretch();

    if (count == 0) {
        QLabel *aucunProjet = new QLabel("Aucun projet pour le moment.\nCliquez sur 'Nouveau Projet' pour commencer !");
        aucunProjet->setAlignment(Qt::AlignCenter);
        aucunProjet->setStyleSheet(
            "color: #95a5a6;"
            "font-size: 16px;"
            "padding: 40px;"
        );
        projectsLayout->insertWidget(0, aucunProjet);
    }

    qDebug() << "✅" << count << "projet(s) affiché(s) sur la page d'accueil";
}

void HomePage::creerCarteProjet(int id, QString nom, QString date)
{
    // Frame principale
    QFrame *card = new QFrame();
    card->setMinimumHeight(80);
    card->setMaximumHeight(100);
    card->setCursor(Qt::PointingHandCursor);
    card->setContextMenuPolicy(Qt::CustomContextMenu);
    card->setStyleSheet(
        "QFrame {"
        "   background-color: white;"
        "   border: 2px solid #ecf0f1;"
        "   border-radius: 10px;"
        "   padding: 15px;"
        "}"
        "QFrame:hover {"
        "   border: 2px solid #3498db;"
        "   background-color: #f8f9fa;"
        "}"
    );

    // Layout horizontal
    QHBoxLayout *cardLayout = new QHBoxLayout(card);
    cardLayout->setSpacing(15);

    // Icône
    QLabel *icon = new QLabel("📁");
    icon->setStyleSheet("font-size: 32px;");

    // Infos du projet
    QVBoxLayout *infoLayout = new QVBoxLayout();
    infoLayout->setSpacing(5);

    QLabel *nomLabel = new QLabel(nom);
    nomLabel->setStyleSheet(
        "font-size: 18px;"
        "font-weight: bold;"
        "color: #2c3e50;"
    );

    QLabel *dateLabel = new QLabel("Créé le : " + date);
    dateLabel->setStyleSheet(
        "font-size: 12px;"
        "color: #7f8c8d;"
    );

    infoLayout->addWidget(nomLabel);
    infoLayout->addWidget(dateLabel);

    cardLayout->addWidget(icon);
    cardLayout->addLayout(infoLayout, 1);
    cardLayout->addStretch();

    // Stocker l'ID dans la carte pour le retrouver au clic
    card->setProperty("projectId", id);
    card->setProperty("projectName", nom);

    // Installer un filtre d'événements pour détecter le clic
    card->installEventFilter(this);

    projectsLayout->insertWidget(projectsLayout->count() - 1, card);
    connect(card, &QFrame::customContextMenuRequested,
            this, &HomePage::showProjectContextMenu);

}

bool HomePage::event(QEvent *event)
{
