bool HomePage::eventFilter(QObject *obj, QEvent *event)
{
    if (event->type() == QEvent::MouseButtonPress) {
        // Dans Qt, on peut directement caster après avoir vérifié le type
        QMouseEvent *mouseEvent = static_cast<QMouseEvent*>(event);
        if (mouseEvent->button() == Qt::LeftButton) {
            QFrame *card = qobject_cast<QFrame*>(obj);
            if (card && card->property("projectId").isValid()) {
                int id = card->property("projectId").toInt();
                QString nom = card->property("projectName").toString();

                qDebug() << "✅ Projet cliqué:" << nom << "ID:" << id;
                emit projetSelectionne(id, nom);
                return true;
            }
        }
    }

    return QWidget::eventFilter(obj, event);
}

