// ✅ NOUVEAU : Afficher le menu contextuel
void HomePage::showProjectContextMenu(const QPoint &pos)
{
    QFrame *card = qobject_cast<QFrame*>(sender());
    if (!card) return;

    if (!card->property("projectId").isValid()) return;

    QMenu contextMenu(this);

    QAction *openAction = contextMenu.addAction("Ouvrir");
    QAction *renameAction = contextMenu.addAction("Renommer");
    QAction *deleteAction = contextMenu.addAction("Supprimer");
    contextMenu.addSeparator();
    QAction *cancelAction = contextMenu.addAction("Annuler");

    QAction *selectedAction = contextMenu.exec(card->mapToGlobal(pos));

    if (selectedAction == openAction) {
        int id = card->property("projectId").toInt();
        QString nom = card->property("projectName").toString();
        emit projetSelectionne(id, nom);
    }
    else if (selectedAction == renameAction) {
        int id = card->property("projectId").toInt();
        QString currentName = card->property("projectName").toString();

        bool ok;
        QString newName = QInputDialog::getText(this,
                                               "Renommer le projet",
                                               "Nouveau nom :",
                                               QLineEdit::Normal,
                                               currentName,
                                               &ok);

        if (ok && !newName.trimmed().isEmpty()) {
            if (newName != currentName) {
                emit projetRenomme(id, newName);
            }
        }
    }
    else if (selectedAction == deleteAction) {
        int id = card->property("projectId").toInt();

        QMessageBox::StandardButton reply;
        reply = QMessageBox::question(this,
                                     "Confirmer la suppression",
                                     "Êtes-vous sûr de vouloir supprimer ce projet ?\n"
                                     "Cette action est irréversible.",
                                     QMessageBox::Yes | QMessageBox::No);

        if (reply == QMessageBox::Yes) {
            emit projetSupprime(id);
        }
    }
}

