// ✅ NOUVEAU : Réinitialiser toute la base de données
void HomePage::resetDatabase()
{
    qDebug() << "⚠️ Demande de réinitialisation de la base de données";

    // Demander confirmation avec un message explicite
    QMessageBox::StandardButton reply;
    reply = QMessageBox::critical(this,
                                 "⚠️ RÉINITIALISATION COMPLÈTE",
                                 "🚨 ATTENTION : ACTION IRRÉVERSIBLE !\n\n"
                                 "Voulez-vous vraiment supprimer :\n"
                                 "• TOUS les projets\n"
                                 "• TOUTES les colonnes\n"
                                 "• TOUTES les cartes\n\n"
                                 "Cette action supprimera définitivement toutes vos données.\n"
                                 "Aucune restauration ne sera possible !",
                                 QMessageBox::Yes | QMessageBox::No,
                                 QMessageBox::No);  // Par défaut sur "Non"

    if (reply != QMessageBox::Yes) {
        qDebug() << "❌ Réinitialisation annulée par l'utilisateur";
        return;
    }

    // Demander une confirmation supplémentaire avec mot de passe
    bool ok;
    QString texte = QInputDialog::getText(this,
                                         "Confirmation finale",
                                         "Pour confirmer, tapez 'SUPPRIMER' :",
                                         QLineEdit::Normal,
                                         "",
                                         &ok);

    if (!ok || texte.toUpper() != "SUPPRIMER") {
        qDebug() << "❌ Réinitialisation annulée : confirmation incorrecte";
        QMessageBox::information(this, "Annulé", "Réinitialisation annulée.");
        return;
    }

    qDebug() << "✅ Confirmation reçue, émission du signal resetDatabaseDemande";

    // Émettre le signal vers MainWindow
    emit resetDatabaseDemande();

    // Rafraîchir l'affichage immédiatement
    chargerProjets();

    QMessageBox::information(this,
                            "Base réinitialisée",
                            "La base de données a été vidée avec succès.\n"
                            "Toutes les données ont été supprimées.");
}

