bool MainWindow::initialiser_base(){

    QSqlQuery req;
    QString sql1 =
        "CREATE TABLE IF NOT EXISTS Projets ("
        "    id_projet INTEGER PRIMARY KEY AUTOINCREMENT,"
        "    nom_projet TEXT NOT NULL,"
        "    date_creation DATETIME DEFAULT CURRENT_TIMESTAMP"
        ");";
      QString sql2=  "CREATE TABLE IF NOT EXISTS Colonnes ("
        "    id_colonne INTEGER PRIMARY KEY AUTOINCREMENT,"
        "    id_projet INTEGER NOT NULL,"
        "    nom TEXT NOT NULL,"
        "    position INTEGER DEFAULT 0,"
        "    FOREIGN KEY (id_projet) REFERENCES Projets(id_projet) ON DELETE CASCADE"
        ");";
       QString sql3= "CREATE TABLE IF NOT EXISTS Cartes ("
        "    id_carte INTEGER PRIMARY KEY AUTOINCREMENT,"
        "    id_colonne INTEGER NOT NULL,"
        "    titre TEXT NOT NULL,"
        "    description TEXT,"
        "    date_echeance DATE,"
        "    priorite TEXT CHECK(priorite IN ('Faible', 'Moyenne', 'Élevée')),"
        "    tags TEXT,"
        "    temps_estime INTEGER DEFAULT 0,"
        "    temps_passe INTEGER DEFAULT 0,"
        "    terminee BOOLEAN DEFAULT 0,"
        "    position INTEGER DEFAULT 0,"
        "    date_creation DATETIME DEFAULT CURRENT_TIMESTAMP,"
        "    FOREIGN KEY (id_colonne) REFERENCES Colonnes(id_colonne) ON DELETE CASCADE"
        ");";;

    bool status = req.exec(sql1) && req.exec(sql2) && req.exec(sql3);

         if(!status){
           QSqlError erreur=req.lastError().text();
           QMessageBox::warning(this,"Erreur d'initialisation de la BD","erreur");

   }
         return status;
}

