void MainWindow::createNewProject(QString project_name){

       Tableau *newTableau = new Tableau(project_name);

        // Ajouter l'onglet au tabWidget
        int tabIndex = tabWidget->addTab(newTableau, project_name);

        // Activer le nouvel onglet
        tabWidget->setCurrentIndex(tabIndex);
        QSqlQuery req;
            req.prepare("INSERT INTO projets (nom_projet) VALUES (:nom)");
            req.bindValue(":nom", project_name);
            if (!req.exec()) {
                qDebug() << "❌ Erreur création projet:" << req.lastError().text();
            }

            // Récupérer l'ID du projet créé
            int project_id = req.lastInsertId().toInt();
            creer_colonnes_initiales(project_id);
            newTableau->setDatabase(&db);      // Donner accès à la base de données
            newTableau->setProjectId(project_id);

            // ✅ BASCULER VERS LE TABWIDGET
              afficherTabWidget();

                // ✅ RAFRAÎCHIR LA PAGE D'ACCUEIL
           homePage->rafraichirListeProjets();

}


