void MainWindow::creer_colonnes_initiales(int project_id){
    QStringList colonnesDefaut = {"TO DO", "DOING", "FINISHED"};
        int position = 0;

        QSqlQuery req;
        req.prepare("INSERT INTO colonnes (id_projet, nom, position) "
                    "VALUES (:projet_id, :nom, :position)");

        foreach (const QString& nomColonne, colonnesDefaut) {
            req.bindValue(":projet_id", project_id);
            req.bindValue(":nom", nomColonne);
            req.bindValue(":position", position++);

            if (!req.exec()) {
                qDebug() << "❌ Erreur création colonne" << nomColonne
                         << ":" << req.lastError().text();
            } else {
                qDebug() << "✅ Colonne créée:" << nomColonne;
            }
        }
}
