void MainWindow::deleteProject(int project_id)
{
    qDebug() << "🗑️ Suppression du projet ID:" << project_id;

    // Vérifier si le projet est ouvert
    bool projectIsOpen = false;
    int openTabIndex = -1;

    for (int i = 0; i < tabWidget->count(); i++) {
        Tableau *tableau = qobject_cast<Tableau*>(tabWidget->widget(i));
        if (tableau && tableau->getProjectId() == project_id) {
            projectIsOpen = true;
            openTabIndex = i;
            break;
        }
    }

    if (projectIsOpen) {
        QMessageBox::StandardButton reply = QMessageBox::question(
            this,
            "Projet ouvert",
            "Ce projet est actuellement ouvert. Voulez-vous le fermer avant de le supprimer ?\n\n"
            "Le projet sera supprimé définitivement de la base de données.",
            QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel
        );

        if (reply == QMessageBox::Cancel) {
            qDebug() << "❌ Suppression annulée";
            return;
        }

        if (reply == QMessageBox::Yes && openTabIndex != -1) {
            // Fermer l'onglet
            tabWidget->removeTab(openTabIndex);
        }
    }

    // Demander confirmation définitive
    QMessageBox::StandardButton confirm = QMessageBox::critical(
        this,
        "Confirmation de suppression",
        "⚠️ Voulez-vous vraiment supprimer définitivement ce projet ?\n\n"
        "Cette action supprimera :\n"
        "• Toutes les cartes du projet\n"
        "• Toutes les colonnes du projet\n"
        "• Le projet lui-même\n\n"
        "Cette action est irréversible !",
        QMessageBox::Yes | QMessageBox::No
    );

    if (confirm != QMessageBox::Yes) {
        qDebug() << "❌ Suppression annulée par l'utilisateur";
        return;
    }

    // Supprimer de la base de données (grâce à ON DELETE CASCADE, tout sera supprimé)
    QSqlQuery req;
    req.prepare("DELETE FROM Projets WHERE id_projet = :id");
    req.bindValue(":id", project_id);

    if (req.exec()) {
        int rowsAffected = req.numRowsAffected();
        if (rowsAffected > 0) {
            qDebug() << "✅ Projet supprimé avec succès (ID:" << project_id << ")";

            // Rafraîchir la page d'accueil
            homePage->rafraichirListeProjets();

            // Vérifier si on doit revenir à la page d'accueil
            if (tabWidget->count() == 0) {
                afficherHomePage();
            }

            QMessageBox::information(this, "Succès", "Le projet a été supprimé avec succès.");
        } else {
            qDebug() << "⚠️ Aucun projet trouvé avec ID:" << project_id;
            QMessageBox::warning(this, "Erreur", "Le projet n'a pas été trouvé.");
        }
    } else {
        qDebug() << "❌ Erreur lors de la suppression:" << req.lastError().text();
        QMessageBox::critical(this, "Erreur BD",
            "Erreur lors de la suppression du projet:\n" + req.lastError().text());
    }
}

// ✅ NOUVEAU : Méthode pour renommer un projet
void MainWindow::renameProject(int project_id, const QString &new_name)
{
    qDebug() << "✏️ Renommage du projet ID:" << project_id << "en:" << new_name;

    if (new_name.trimmed().isEmpty()) {
        QMessageBox::warning(this, "Erreur", "Le nom du projet ne peut pas être vide.");
        return;
    }

    // Vérifier si le nom existe déjà
    QSqlQuery checkQuery;
    checkQuery.prepare("SELECT COUNT(*) FROM Projets WHERE nom_projet = :nom AND id_projet != :id");
    checkQuery.bindValue(":nom", new_name);
    checkQuery.bindValue(":id", project_id);

    if (checkQuery.exec() && checkQuery.next()) {
        int count = checkQuery.value(0).toInt();
        if (count > 0) {
            QMessageBox::warning(this, "Erreur",
                "Un projet avec ce nom existe déjà. Veuillez choisir un autre nom.");
            return;
        }
    }

    // Mettre à jour dans la base de données
    QSqlQuery req;
    req.prepare("UPDATE Projets SET nom_projet = :nom WHERE id_projet = :id");
    req.bindValue(":nom", new_name);
    req.bindValue(":id", project_id);

    if (req.exec()) {
        int rowsAffected = req.numRowsAffected();
        if (rowsAffected > 0) {
            qDebug() << "✅ Projet renommé avec succès";

            // Mettre à jour l'onglet si le projet est ouvert
            for (int i = 0; i < tabWidget->count(); i++) {
                Tableau *tableau = qobject_cast<Tableau*>(tabWidget->widget(i));
                if (tableau && tableau->getProjectId() == project_id) {
                    tabWidget->setTabText(i, new_name);
                    break;
                }
            }

            // Rafraîchir la page d'accueil
            homePage->rafraichirListeProjets();

            QMessageBox::information(this, "Succès", "Le projet a été renommé avec succès.");
        } else {
            qDebug() << "⚠️ Aucun projet trouvé avec ID:" << project_id;
            QMessageBox::warning(this, "Erreur", "Le projet n'a pas été trouvé.");
        }
    } else {
        qDebug() << "❌ Erreur lors du renommage:" << req.lastError().text();
        QMessageBox::critical(this, "Erreur BD",
            "Erreur lors du renommage du projet:\n" + req.lastError().text());
    }
}

// ✅ NOUVEAU : Slot pour renommer un projet
void MainWindow::onProjectRenamed(int project_id, const QString &new_name)
{
    renameProject(project_id, new_name);
}

// ✅ NOUVEAU : Slot pour supprimer un projet
void MainWindow::onProjectDeleted(int project_id)
{
    deleteProject(project_id);
}

// ✅ NOUVEAU : Réinitialiser complètement la base de données
void MainWindow::onResetDatabase()
{
    qDebug() << "🗑️ Réinitialisation complète de la base demandée";

        // Vérifier s'il y a des projets ouverts
        bool hasOpenProjects = false;
        QList<int> openProjectIds;

        for (int i = 0; i < tabWidget->count(); i++) {
            Tableau *tableau = qobject_cast<Tableau*>(tabWidget->widget(i));
            if (tableau) {
                hasOpenProjects = true;
                openProjectIds << tableau->getProjectId();
            }
        }

        if (hasOpenProjects) {
            // Récupérer les noms des projets depuis la BD
            QStringList openProjectNames;
            QSqlQuery query;
            foreach (int projectId, openProjectIds) {
                query.prepare("SELECT nom_projet FROM Projets WHERE id_projet = ?");
                query.addBindValue(projectId);
                if (query.exec() && query.next()) {
                    openProjectNames << query.value(0).toString();
                } else {
                    openProjectNames << QString("Projet ID:%1").arg(projectId);
                }
            }

            QString message = "Des projets sont actuellement ouverts :\n";
            foreach (QString name, openProjectNames) {
                message += "• " + name + "\n";
            }
            message += "\nVoulez-vous fermer tous les projets avant de continuer ?";

            QMessageBox::StandardButton reply = QMessageBox::question(
                this,
                "Projets ouverts",
                message,
                QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel
            );

            if (reply == QMessageBox::Cancel) {
                qDebug() << "❌ Réinitialisation annulée";
                return;
            }

            if (reply == QMessageBox::Yes) {
                // Fermer tous les onglets
                while (tabWidget->count() > 0) {
                    tabWidget->removeTab(0);
                }
                // Revenir à la homepage
                afficherHomePage();
            }
        }


    // Réinitialiser la base de données
    QSqlQuery query;

    // Désactiver les clés étrangères pour pouvoir supprimer dans n'importe quel ordre
    query.exec("PRAGMA foreign_keys = OFF");

    // Supprimer toutes les tables (dans l'ordre inverse de création)
    bool success = true;

    if (!query.exec("DELETE FROM Cartes")) {
        qDebug() << "❌ Erreur suppression Cartes:" << query.lastError().text();
        success = false;
    } else {
        qDebug() << "✅ Cartes supprimées :" << query.numRowsAffected() << "lignes";
    }

    if (!query.exec("DELETE FROM Colonnes")) {
        qDebug() << "❌ Erreur suppression Colonnes:" << query.lastError().text();
        success = false;
    } else {
        qDebug() << "✅ Colonnes supprimées :" << query.numRowsAffected() << "lignes";
    }

    if (!query.exec("DELETE FROM Projets")) {
        qDebug() << "❌ Erreur suppression Projets:" << query.lastError().text();
        success = false;
    } else {
        qDebug() << "✅ Projets supprimés :" << query.numRowsAffected() << "lignes";
    }

    // Réactiver les clés étrangères
    query.exec("PRAGMA foreign_keys = ON");

    // Réinitialiser les auto-increments
    query.exec("DELETE FROM sqlite_sequence WHERE name IN ('Projets', 'Colonnes', 'Cartes')");

    if (success) {
        qDebug() << "✅ Base de données réinitialisée avec succès";

        // Rafraîchir la homepage
        homePage->rafraichirListeProjets();

        QMessageBox::information(this,
                                "Succès",
                                "Base de données réinitialisée avec succès.\n"
                                "Toutes les données ont été supprimées.");
    } else {
        qDebug() << "❌ Erreur lors de la réinitialisation";
        QMessageBox::critical(this,
                             "Erreur",
                             "Une erreur est survenue lors de la réinitialisation.\n"
                             "Veuillez vérifier les logs.");
    }
}

