Open_projectalog::Open_project_dialog(QSqlDatabase *database, QWidget *parent) :
    QDialog(parent),
    ui(new Ui::Open_project_dialog),
    db(database)
{
    ui->setupUi(this);
    setWindowTitle("Ouvrir un Projet");

    // Configuration du tableau
    ui->tableWidget->setColumnCount(3);
    ui->tableWidget->setHorizontalHeaderLabels({"ID", "Nom du Projet", "Date de Création"});
    ui->tableWidget->setSelectionBehavior(QAbstractItemView::SelectRows);
    ui->tableWidget->setSelectionMode(QAbstractItemView::SingleSelection);
    ui->tableWidget->setEditTriggers(QAbstractItemView::NoEditTriggers);

    // Cacher la colonne ID
    ui->tableWidget->setColumnHidden(0, true);

    // Ajuster la largeur des colonnes
    ui->tableWidget->setColumnWidth(1, 250);
    ui->tableWidget->setColumnWidth(2, 150);

    // Charger les projets
    chargerProjets();

    // Connexions
    connect(ui->tableWidget, &QTableWidget::itemDoubleClicked,
            this, &OpenProjectDialog::on_tableWidget_itemDoubleClicked);
}

OpenProjectDialog::~OpenProjectDialog()
{
    delete ui;
}

void OpenProjectDialog::chargerProjets()
{
    if (!db || !db->isOpen()) {
        QMessageBox::warning(this, "Erreur", "Base de données non disponible");
        return;
    }

    qDebug() << "🔄 Chargement de la liste des projets...";

    QSqlQuery req(*db);
    req.prepare("SELECT id_projet, nom_projet, date_creation FROM Projets ORDER BY date_creation DESC");

    if (!req.exec()) {
        QMessageBox::warning(this, "Erreur", "Impossible de charger les projets:\n" + req.lastError().text());
        return;
    }

    ui->tableWidget->setRowCount(0);
    int row = 0;

    while (req.next()) {
        int id = req.value(0).toInt();
        QString nom = req.value(1).toString();
        QString date = req.value(2).toString();

        ui->tableWidget->insertRow(row);

        // Colonne 0 : ID (cachée)
        QTableWidgetItem *itemId = new QTableWidgetItem(QString::number(id));
        ui->tableWidget->setItem(row, 0, itemId);

        // Colonne 1 : Nom
        QTableWidgetItem *itemNom = new QTableWidgetItem("📁 " + nom);
        ui->tableWidget->setItem(row, 1, itemNom);

        // Colonne 2 : Date
        QTableWidgetItem *itemDate = new QTableWidgetItem(date);
        ui->tableWidget->setItem(row, 2, itemDate);

        row++;
    }

    qDebug() << "✅" << row << "projet(s) chargé(s)";

    if (row == 0) {
        QMessageBox::information(this, "Information", "Aucun projet disponible.\nCréez d'abord un nouveau projet.");
    }
}

void OpenProjectDialog::on_tableWidget_itemDoubleClicked(QTableWidgetItem *item)
{
    // Double-clic = ouvrir directement
    int row = item->row();
    selectedProjectId = ui->tableWidget->item(row, 0)->text().toInt();
    selectedProjectName = ui->tableWidget->item(row, 1)->text().replace("📁 ", "");

    qDebug() << "✅ Projet sélectionné (double-clic):" << selectedProjectName << "ID:" << selectedProjectId;
    accept();
}

void OpenProjectDialog::on_btnOpen_clicked()
{
    QList<QTableWidgetItem*> selected = ui->tableWidget->selectedItems();

    if (selected.isEmpty()) {
        QMessageBox::warning(this, "Attention", "Veuillez sélectionner un projet");
        return;
    }

    int row = ui->tableWidget->currentRow();
    selectedProjectId = ui->tableWidget->item(row, 0)->text().toInt();
    selectedProjectName = ui->tableWidget->item(row, 1)->text().replace("📁 ", "");

    qDebug() << "✅ Projet sélectionné (bouton):" << selectedProjectName << "ID:" << selectedProjectId;
    accept();
}

void OpenProjectDialog::on_btnCancel_clicked()
{
    reject();
}

int OpenProjectDialog::getSelectedProjectId() const
{
    return selectedProjectId;
}

QString OpenProjectDialog::getSelectedProjectName() const
{
    return selectedProjectName;
}

