void StatsWidget::refreshStats()
{
    if (!db) {
            qDebug() << "❌ Pointeur DB null";
            return;
        }

        if (!db->isOpen()) {
            qDebug() << "❌ DB non ouverte";
            return;
        }
    // Mettre à jour les cartes
    int total = getTotalCards();
    int completed = getCompletedCards();
    int inProgress = getInProgressCards();
    int overdue = getOverdueCards();

    totalCardsCard->findChild<QLabel*>("valueLabel")->setText(QString::number(total));
    completedCardsCard->findChild<QLabel*>("valueLabel")->setText(QString::number(completed));
    inProgressCardsCard->findChild<QLabel*>("valueLabel")->setText(QString::number(inProgress));
    overdueCardsCard->findChild<QLabel*>("valueLabel")->setText(QString::number(overdue));

    // Mettre à jour les graphiques
    createPriorityChart();
    createTimeAnalysisChart();
    createProgressChart();
    createColumnDistributionChart();

    qDebug() << "✅ Statistiques rafraîchies";
}

// ========== MÉTHODES DE CALCUL ==========

int StatsWidget::getTotalCards()
{
    QSqlQuery query(*db);
    query.prepare("SELECT COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec() && query.next()) {
        return query.value(0).toInt();
    }
    return 0;
}

int StatsWidget::getCompletedCards()
{
    QSqlQuery query(*db);
    query.prepare("SELECT COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id AND c.terminee = 1");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec() && query.next()) {
        return query.value(0).toInt();
    }
    return 0;
}

int StatsWidget::getInProgressCards()
{
    QSqlQuery query(*db);
    query.prepare("SELECT COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id AND c.terminee = 0 "
                  "AND col.nom IN ('DOING', 'TO DO')");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec() && query.next()) {
        return query.value(0).toInt();
    }
    return 0;
}

int StatsWidget::getOverdueCards()
{
    QSqlQuery query(*db);
    query.prepare("SELECT COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id "
                  "AND c.terminee = 0 "
                  "AND c.date_echeance < date('now')");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec() && query.next()) {
        return query.value(0).toInt();
    }
    return 0;
}

QMap<QString, int> StatsWidget::getPriorityDistribution()
{
    QMap<QString, int> distribution;

    QSqlQuery query(*db);
    query.prepare("SELECT priorite, COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id "
                  "GROUP BY priorite");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec()) {
        while (query.next()) {
            QString priority = query.value(0).toString();
            int count = query.value(1).toInt();
            distribution[priority] = count;
        }
    }

    return distribution;
}

QPair<int, int> StatsWidget::getTimeStats()
{
    int totalEstimated = 0;
    int totalSpent = 0;

    QSqlQuery query(*db);
    query.prepare("SELECT SUM(temps_estime), SUM(temps_passe) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec() && query.next()) {
        totalEstimated = query.value(0).toInt();
        totalSpent = query.value(1).toInt();
    }

    return qMakePair(totalEstimated, totalSpent);
}

QMap<QString, int> StatsWidget::getColumnDistribution()
{
    QMap<QString, int> distribution;

    QSqlQuery query(*db);
    query.prepare("SELECT col.nom, COUNT(*) FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id "
                  "GROUP BY col.nom");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec()) {
        while (query.next()) {
            QString column = query.value(0).toString();
            int count = query.value(1).toInt();
            distribution[column] = count;
        }
    }

    return distribution;
}

QStringList StatsWidget::getTopTags(int limit)
{
    QStringList topTags;
    QMap<QString, int> tagCounts;

    QSqlQuery query(*db);
    query.prepare("SELECT tags FROM Cartes c "
                  "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                  "WHERE col.id_projet = :projet_id AND tags != ''");
    query.bindValue(":projet_id", m_projectId);

    if (query.exec()) {
        while (query.next()) {
            QString tagsStr = query.value(0).toString();
            QStringList tags = tagsStr.split(",", QString::SkipEmptyParts);
            for (const QString &tag : tags) {
                QString trimmedTag = tag.trimmed();
                if (!trimmedTag.isEmpty()) {
                    tagCounts[trimmedTag]++;
                }
            }
        }
    }

    // Trier par fréquence
    QList<QPair<QString, int>> sortedTags;
    for (auto it = tagCounts.begin(); it != tagCounts.end(); ++it) {
        sortedTags.append(qMakePair(it.key(), it.value()));
    }

    std::sort(sortedTags.begin(), sortedTags.end(),
              [](const QPair<QString, int> &a, const QPair<QString, int> &b) {
                  return a.second > b.second;
              });

    for (int i = 0; i < qMin(limit, sortedTags.size()); ++i) {
        topTags.append(sortedTags[i].first);
    }

    return topTags;
}

// ========== CRÉATION DES GRAPHIQUES ==========

void StatsWidget::createPriorityChart()
{
    QMap<QString, int> distribution = getPriorityDistribution();

    QPieSeries *series = new QPieSeries();

    QMap<QString, QColor> colors;
    colors["Élevée"] = QColor("#e74c3c");
    colors["Moyenne"] = QColor("#f39c12");
    colors["Faible"] = QColor("#2ecc71");

    int total = getTotalCards();
    if (total == 0) total = 1; // Éviter division par zéro

    for (auto it = distribution.begin(); it != distribution.end(); ++it) {
        QPieSlice *slice = series->append(it.key(), it.value());
        slice->setLabelVisible(true);

        double percentage = (100.0 * it.value()) / total;
        QString label = QString("%1: %2 (%3%)")
                        .arg(it.key())
                        .arg(it.value())
                        .arg(percentage, 0, 'f', 1);
        slice->setLabel(label);

        if (colors.contains(it.key())) {
            slice->setColor(colors[it.key()]);
        }
    }

    QChart *chart = new QChart();
    chart->addSeries(series);
    chart->setTitle("");
    chart->legend()->setAlignment(Qt::AlignBottom);
    chart->setAnimationOptions(QChart::SeriesAnimations);

    priorityChartView->setChart(chart);
}

void StatsWidget::createTimeAnalysisChart()
{
    QPair<int, int> timeStats = getTimeStats();

    QBarSet *set = new QBarSet("Heures");
    *set << timeStats.first << timeStats.second;

    QBarSeries *series = new QBarSeries();
    series->append(set);
    series->setBarWidth(0.5);

    // Couleurs
    set->setColor(QColor("#3498db"));

    QChart *chart = new QChart();
    chart->addSeries(series);
    chart->setTitle("");
    chart->setAnimationOptions(QChart::SeriesAnimations);

    QStringList categories;
    categories << "Estimé" << "Passé";

    QBarCategoryAxis *axisX = new QBarCategoryAxis();
    axisX->append(categories);
    chart->addAxis(axisX, Qt::AlignBottom);
    series->attachAxis(axisX);

    QValueAxis *axisY = new QValueAxis();
    axisY->setTitleText("Heures");
    chart->addAxis(axisY, Qt::AlignLeft);
    series->attachAxis(axisY);

    chart->legend()->setVisible(false);

    timeChartView->setChart(chart);
}

void StatsWidget::createProgressChart()
{
    QLineSeries *createdSeries = new QLineSeries();
    createdSeries->setName("Créées");
    createdSeries->setColor(QColor("#3498db"));

    QLineSeries *completedSeries = new QLineSeries();
    completedSeries->setName("Terminées");
    completedSeries->setColor(QColor("#2ecc71"));

    // ✅ CORRECTION: Utiliser QRandomGenerator correctement
    QDate today = QDate::currentDate();
    for (int i = 30; i >= 0; i--) {
        QDate date = today.addDays(-i);

        // ✅ Créer un générateur ou utiliser global() correctement
        int randomCreated = QRandomGenerator::global()->bounded(10);
        int randomCompleted = QRandomGenerator::global()->bounded(8);

        createdSeries->append(date.toJulianDay(), randomCreated);
        completedSeries->append(date.toJulianDay(), randomCompleted);
    }

    QChart *chart = new QChart();
    chart->addSeries(createdSeries);
    chart->addSeries(completedSeries);
    chart->setTitle("");
    chart->setAnimationOptions(QChart::SeriesAnimations);

    QDateTimeAxis *axisX = new QDateTimeAxis();
    axisX->setFormat("dd MMM");
    axisX->setTitleText("Date");
    chart->addAxis(axisX, Qt::AlignBottom);
    createdSeries->attachAxis(axisX);
    completedSeries->attachAxis(axisX);

    QValueAxis *axisY = new QValueAxis();
    axisY->setTitleText("Cartes");
    chart->addAxis(axisY, Qt::AlignLeft);
    createdSeries->attachAxis(axisY);
    completedSeries->attachAxis(axisY);

    chart->legend()->setAlignment(Qt::AlignTop);

    progressChartView->setChart(chart);
}

void StatsWidget::createColumnDistributionChart()
{
    QMap<QString, int> distribution = getColumnDistribution();

    QBarSet *set = new QBarSet("Cartes");
    QStringList categories;

    QMap<QString, QColor> colors;
    colors["TO DO"] = QColor("#3498db");
    colors["DOING"] = QColor("#f39c12");
    colors["FINISHED"] = QColor("#2ecc71");

    for (auto it = distribution.begin(); it != distribution.end(); ++it) {
        categories << it.key();
        *set << it.value();
    }

    set->setColor(QColor("#9b59b6"));

    QBarSeries *series = new QBarSeries();
    series->append(set);

    QChart *chart = new QChart();
    chart->addSeries(series);
    chart->setTitle("");
    chart->setAnimationOptions(QChart::SeriesAnimations);

    QBarCategoryAxis *axisX = new QBarCategoryAxis();
    axisX->append(categories);
    chart->addAxis(axisX, Qt::AlignBottom);
    series->attachAxis(axisX);

    QValueAxis *axisY = new QValueAxis();
    axisY->setTitleText("Nombre de cartes");
    chart->addAxis(axisY, Qt::AlignLeft);
    series->attachAxis(axisY);

    chart->legend()->setVisible(false);

    columnChartView->setChart(chart);
}

