                insert.bindValue(":date", dates);
                insert.bindValue(":priorite", card_taskPriority);
                insert.bindValue(":tags", card_taskTags.join(","));
                insert.bindValue(":temps_estime", card_estimatedTime);  // ✅ NOUVEAU
                insert.bindValue(":temps_passe", card_spentTime);       // ✅ NOUVEAU

