                    qDebug() << "❌ Erreur sauvegarde carte:" << insert.lastError().text();
                }
            } else {
                qDebug() << "❌ Colonne TO DO introuvable:" << req.lastError().text();
            }
        } else {
            qDebug() << "⚠️ Base de données non disponible";
        }

        // Afficher la carte
        Card *newCard = new Card(card_taskName, card_taskDescription, dates, card_taskPriority, this);
