void Tableau::chargerCartesDepuisBD() {
    if (!db || !db->isOpen() || project_id == -1) {
        qDebug() << "⚠️ Impossible de charger les cartes: BD ou projectId invalide";
        return;
    }

    qDebug() << "📖 Chargement des cartes pour le projet" << project_id;

    // 1️⃣ Charger d'abord toutes les colonnes du projet
    QSqlQuery reqCol(*db);
    reqCol.prepare("SELECT id_colonne, nom, position FROM Colonnes "
                   "WHERE id_projet = :projet_id "
                   "ORDER BY position");
    reqCol.bindValue(":projet_id", project_id);

    if (!reqCol.exec()) {
        qDebug() << "❌ Erreur chargement colonnes:" << reqCol.lastError().text();
        return;
    }

    // 2️⃣ Créer les colonnes personnalisées (position > 2)
    while (reqCol.next()) {
        int id_colonne = reqCol.value(0).toInt();
        QString nom = reqCol.value(1).toString();
        int position = reqCol.value(2).toInt();

        if (position > 2) {
            creerColonnePersonnalisee(nom, id_colonne);
        }
    }

    // 3️⃣ Charger toutes les cartes avec les champs de temps ✅
    QSqlQuery req(*db);
    req.prepare("SELECT c.id_carte, c.titre, c.description, c.date_echeance, c.priorite, c.tags, "
                "c.temps_estime, c.temps_passe, "  // ✅ AJOUT DES CHAMPS TEMPS
                "col.nom, col.id_colonne "
                "FROM Cartes c "
                "JOIN Colonnes col ON c.id_colonne = col.id_colonne "
                "WHERE col.id_projet = :projet_id "
                "ORDER BY col.position, c.position");
    req.bindValue(":projet_id", project_id);

    if (!req.exec()) {
        qDebug() << "❌ Erreur chargement cartes:" << req.lastError().text();
        return;
    }

    int cartes_chargees = 0;

    while (req.next()) {
        int id_carte = req.value(0).toInt();
        QString titre = req.value(1).toString();
        QString description = req.value(2).toString();
        QString date = req.value(3).toString();
        QString priorite = req.value(4).toString();
        QString tagsStr = req.value(5).toString();
        int temps_estime = req.value(6).toInt();   // ✅ NOUVEAU - index 6
        int temps_passe = req.value(7).toInt();    // ✅ NOUVEAU - index 7
        QString nomColonne = req.value(8).toString();  // index 8
        int id_colonne = req.value(9).toInt();         // index 9

        qDebug() << "📦 Chargement carte:" << titre << "| Temps:" << temps_estime << "h estimé," << temps_passe << "h passé";

        QStringList tags;
        if (!tagsStr.isEmpty()) {
            tags = tagsStr.split(",");
        }

        // Créer la carte
        Card *newCard = new Card(titre, description, date, priorite, this);
        newCard->setAcceptDrops(true);
        newCard->setCardId(id_carte);
        newCard->setTags(tags);
        newCard->setEstimatedTime(temps_estime);  // ✅ NOUVEAU
        newCard->setSpentTime(temps_passe);       // ✅ NOUVEAU

        if (nomColonne == "FINISHED") {
            newCard->findChild<QCheckBox*>()->blockSignals(true);
            newCard->findChild<QCheckBox*>()->setChecked(true);
            newCard->findChild<QCheckBox*>()->blockSignals(false);
        }

        // Ajouter dans la bonne colonne
        QVBoxLayout *targetLayout = nullptr;

        if (nomColonne == "TO DO") {
            targetLayout = ui->verticalLayoutTodo;
        }
        else if (nomColonne == "DOING") {
            targetLayout = ui->verticalLayoutDoing;
        }
        else if (nomColonne == "FINISHED") {
            targetLayout = ui->verticalLayoutFinished;
        }
        else {
            // Colonne personnalisée
            for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
                if (col.id_colonne == id_colonne) {
                    targetLayout = col.layout;
                    break;
                }
            }
        }

        if (targetLayout) {
            int pos = targetLayout->count();
            targetLayout->insertWidget(pos, newCard);
            qDebug() << "  📌 Carte ajoutée dans" << nomColonne << ":" << titre
                     << "Temps:" << temps_estime << "h estimé," << temps_passe << "h passé";
            cartes_chargees++;
        }
    }

    qDebug() << "✅" << cartes_chargees << "carte(s) chargée(s)";
}
