void Tableau::modifierCarte(Card* card)
{
    if (!card) {
        qDebug() << "❌ Carte nulle";
        return;
    }

    // 1. RÉCUPÉRER LES DONNÉES ACTUELLES DE LA CARTE
    QString currentTitle = card->getTitle();
    QString currentDescription = card->getDescription();
    QString currentDateStr = card->getDate();
    QString currentPriority = card->getPriority();
    QStringList currentTags = card->getTags();
    int currentEstimatedTime = card->getEstimatedTime();  // ✅ NOUVEAU
    int currentSpentTime = card->getSpentTime();          // ✅ NOUVEAU

    qDebug() << "📝 Modification carte:";
    qDebug() << "   Titre actuel:" << currentTitle;
    qDebug() << "   Tags actuels:" << currentTags;
    qDebug() << "   Temps estimé:" << currentEstimatedTime << "h";  // ✅ NOUVEAU
    qDebug() << "   Temps passé:" << currentSpentTime << "h";       // ✅ NOUVEAU

    // 2. PRÉ-REMPLIR LE DIALOGUE AVEC LES VALEURS ACTUELLES
    card_Dialog->taskName = currentTitle;
    card_Dialog->taskDescription = currentDescription;
    card_Dialog->taskPriority = currentPriority;

    QDate currentDate = QDate::fromString(currentDateStr);
    if (!currentDate.isValid()) {
        currentDate = QDate::currentDate();
    }
    card_Dialog->taskDate = currentDate;

    card_Dialog->setDialogText(currentTitle);
    card_Dialog->setDialogDescription(currentDescription);
    card_Dialog->setDialogTags(currentTags);
    card_Dialog->setDialogTime(currentEstimatedTime, currentSpentTime);  // ✅ NOUVEAU

    // 3. OUVRIR LE DIALOGUE
    card_Dialog->open();

    while(card_Dialog->exec() == QDialog::Accepted && card_Dialog->taskName == "") {
        QMessageBox::warning(this, "Erreur", "Le nom de la carte ne peut pas être vide");
        card_Dialog->open();
    }

    if (card_Dialog->result() == QDialog::Rejected) {
        qDebug() << "❌ Modification annulée";
        return;
    }

    // 4. RÉCUPÉRER LES NOUVELLES VALEURS
    QString newTitle = card_Dialog->taskName;
    QString newDescription = card_Dialog->taskDescription;
    QDate newDate = card_Dialog->taskDate;
    QString newPriority = card_Dialog->taskPriority;
    QStringList newTags = card_Dialog->taskTags;
    int newEstimatedTime = card_Dialog->taskEstimatedTime;  // ✅ NOUVEAU
    int newSpentTime = card_Dialog->taskSpentTime;          // ✅ NOUVEAU
    QString newDateStr = newDate.toString("ddd MMM dd yyyy");

    qDebug() << "🔄 Nouvelles valeurs:";
    qDebug() << "   Nouveaux tags:" << newTags;
    qDebug() << "   Nouveau temps estimé:" << newEstimatedTime << "h";  // ✅ NOUVEAU
    qDebug() << "   Nouveau temps passé:" << newSpentTime << "h";       // ✅ NOUVEAU

    // 5. METTRE À JOUR LA BASE DE DONNÉES
    int carte_id = card->getCardId();

    if (carte_id != -1 && db && db->isOpen()) {
        QSqlQuery req(*db);
        // ✅ AJOUTER LES CHAMPS temps_estime ET temps_passe
        req.prepare("UPDATE Cartes SET titre = :titre, description = :description, "
                   "date_echeance = :date, priorite = :priorite, tags = :tags, "
                   "temps_estime = :temps_estime, temps_passe = :temps_passe "  // ✅ NOUVEAU
                   "WHERE id_carte = :id");

        req.bindValue(":id", carte_id);
        req.bindValue(":titre", newTitle);
        req.bindValue(":description", newDescription);
        req.bindValue(":date", newDateStr);
        req.bindValue(":priorite", newPriority);
