            QMessageBox::warning(this, "Erreur BD", "Impossible de mettre à jour la carte: " + req.lastError().text());
        }
    }

    // 6. METTRE À JOUR L'OBJET CARD
    card->setTask(newTitle);
    card->setDescription(newDescription);
    card->setDate(newDateStr);
    card->setPriority(newPriority);
    card->setTags(newTags);
    card->setEstimatedTime(newEstimatedTime);  // ✅ NOUVEAU
    card->setSpentTime(newSpentTime);          // ✅ NOUVEAU

    // 7. METTRE À JOUR L'AFFICHAGE DE LA CARTE
    QString completed_task = newTitle + "\n" + newDescription + "\n" + newDateStr;
    card->setTitle(completed_task);

    QLabel* titleLabel = card->findChild<QLabel*>();
