// âœ… Version complÃ¨te de handleDropInColumn avec support des colonnes personnalisÃ©es

void Tableau::handleDropInColumn(QDropEvent *event, QVBoxLayout *targetLayout, const QString &columnName)
{
    if (!event->mimeData()->hasFormat("application/x-card")) {
        event->ignore();
        return;
    }

    // RÃ©cupÃ©rer l'ID de la carte
    QByteArray cardData = event->mimeData()->data("application/x-card");
    int cardId = cardData.toInt();

    qDebug() << "ðŸ”„ DÃ©placement carte ID" << cardId << "vers colonne" << columnName;

    // 1. Trouver la carte source dans TOUTES les colonnes
    Card *cardToMove = nullptr;
    QVBoxLayout *sourceLayout = nullptr;

    // Chercher dans TO DO
    for (int i = 0; i < ui->verticalLayoutTodo->count(); i++) {
        QLayoutItem *item = ui->verticalLayoutTodo->itemAt(i);
        if (item && item->widget()) {
            Card *card = qobject_cast<Card*>(item->widget());
            if (card && card->getCardId() == cardId) {
                cardToMove = card;
                sourceLayout = ui->verticalLayoutTodo;
                qDebug() << "âœ… Carte trouvÃ©e dans TO DO";
                break;
            }
        }
    }

    // Chercher dans DOING
    if (!cardToMove) {
        for (int i = 0; i < ui->verticalLayoutDoing->count(); i++) {
            QLayoutItem *item = ui->verticalLayoutDoing->itemAt(i);
            if (item && item->widget()) {
                Card *card = qobject_cast<Card*>(item->widget());
                if (card && card->getCardId() == cardId) {
                    cardToMove = card;
                    sourceLayout = ui->verticalLayoutDoing;
                    qDebug() << "âœ… Carte trouvÃ©e dans DOING";
                    break;
                }
            }
        }
    }

    // Chercher dans FINISHED
    if (!cardToMove) {
        for (int i = 0; i < ui->verticalLayoutFinished->count(); i++) {
            QLayoutItem *item = ui->verticalLayoutFinished->itemAt(i);
            if (item && item->widget()) {
                Card *card = qobject_cast<Card*>(item->widget());
                if (card && card->getCardId() == cardId) {
                    cardToMove = card;
                    sourceLayout = ui->verticalLayoutFinished;
                    qDebug() << "âœ… Carte trouvÃ©e dans FINISHED";
                    break;
                }
            }
        }
    }

    // âœ… NOUVEAU: Chercher dans les colonnes personnalisÃ©es
    if (!cardToMove) {
        for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
            for (int i = 0; i < col.layout->count(); i++) {
                QLayoutItem *item = col.layout->itemAt(i);
                if (item && item->widget()) {
                    Card *card = qobject_cast<Card*>(item->widget());
                    if (card && card->getCardId() == cardId) {
                        cardToMove = card;
                        sourceLayout = col.layout;
                        qDebug() << "âœ… Carte trouvÃ©e dans" << col.nom;
                        break;
                    }
                }
            }
            if (cardToMove) break;
        }
    }

    if (!cardToMove) {
        qDebug() << "âŒ Carte non trouvÃ©e avec ID:" << cardId;
        event->ignore();
        return;
    }

    qDebug() << "âœ… Carte trouvÃ©e:" << cardToMove->getTitle();

    // 2. Si pas de targetLayout (colonne personnalisÃ©e), le trouver
    if (!targetLayout) {
        // Chercher dans les colonnes fixes
        if (columnName == "TO DO") {
            targetLayout = ui->verticalLayoutTodo;
        }
        else if (columnName == "DOING") {
            targetLayout = ui->verticalLayoutDoing;
        }
        else if (columnName == "FINISHED") {
            targetLayout = ui->verticalLayoutFinished;
        }
        else {
            // Chercher dans les colonnes personnalisÃ©es
            for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
                if (col.nom == columnName) {
                    targetLayout = col.layout;
                    break;
                }
            }
        }
    }

    if (!targetLayout) {
        qDebug() << "âŒ Layout de destination non trouvÃ©";
        event->ignore();
        return;
    }

    // 3. VÃ©rifier qu'on ne dÃ©place pas vers la mÃªme colonne
    if (sourceLayout == targetLayout) {
        qDebug() << "âš ï¸ MÃªme colonne, annulation";
        cardToMove->updateCardStyle();
        event->ignore();
        return;
    }

    // 4. Mettre Ã  jour la base de donnÃ©es
    if (db && db->isOpen()) {
        // Trouver l'ID de la colonne de destination
        int id_colonne_dest = -1;

        // Colonnes fixes
        QSqlQuery req(*db);
        req.prepare("SELECT id_colonne FROM Colonnes WHERE id_projet = :projet_id AND nom = :nom");
        req.bindValue(":projet_id", project_id);
        req.bindValue(":nom", columnName);

        if (req.exec() && req.next()) {
            id_colonne_dest = req.value(0).toInt();
        }

        if (id_colonne_dest != -1) {
            // Mettre Ã  jour la carte dans la BD
            QSqlQuery update(*db);
            update.prepare("UPDATE Cartes SET id_colonne = :id_colonne WHERE id_carte = :id_carte");
            update.bindValue(":id_colonne", id_colonne_dest);
            update.bindValue(":id_carte", cardId);

            if (update.exec()) {
                qDebug() << "âœ… BD mise Ã  jour: carte" << cardId << "dÃ©placÃ©e vers" << columnName;
            } else {
                qDebug() << "âŒ Erreur BD:" << update.lastError().text();
            }
        }
    }

    // 5. Retirer la carte de l'ancien layout
    sourceLayout->removeWidget(cardToMove);

    // 6. Trouver l'index oÃ¹ insÃ©rer
    int insertPosition = targetLayout->count();

    // 7. Ajouter la carte au nouveau layout
    targetLayout->insertWidget(insertPosition, cardToMove);

    // 8. Restaurer le style de la carte
    cardToMove->updateCardStyle();

    // 9. Accepter l'Ã©vÃ©nement
    event->acceptProposedAction();

    qDebug() << "ðŸŽ¯ Carte dÃ©placÃ©e avec succÃ¨s vers" << columnName;
}

