QJsonArray Tableau::exporterCartesVersJson(QVBoxLayout *layout)
{
    QJsonArray cartesArray;

    // Parcourir toutes les cartes du layout
    for (int i = 0; i < layout->count(); i++) {
        QLayoutItem *item = layout->itemAt(i);
        if (!item || !item->widget()) continue;

        Card *card = qobject_cast<Card*>(item->widget());
        if (!card) continue;

        // CrÃ©er un objet JSON pour cette carte
        QJsonObject cardObj;
        cardObj["id"] = card->getCardId();
        cardObj["titre"] = card->getTitle();
        cardObj["description"] = card->getDescription();
        cardObj["date_echeance"] = card->getDate();
        cardObj["priorite"] = card->getPriority();
        cardObj["terminee"] = card->isCompleted();

        cartesArray.append(cardObj);
    }

    return cartesArray;
}


