    // ðŸ”§ FONCTION AUXILIAIRE: Exporter les cartes d'un layout vers CSV
    int Tableau::exporterCartesVersCSV(QTextStream &out, QVBoxLayout *layout, const QString &nomColonne)
    {
        int count = 0;

        // Parcourir toutes les cartes du layout
        for (int i = 0; i < layout->count(); i++) {
            QLayoutItem *item = layout->itemAt(i);
            if (!item || !item->widget()) continue;

            Card *card = qobject_cast<Card*>(item->widget());
            if (!card) continue;

            // Ã‰chapper les guillemets et virgules dans les champs
            QString titre = escaperCSV(card->getTitle());
            QString description = escaperCSV(card->getDescription());
            QString date = card->getDate();
            QString priorite = card->getPriority();
            QString terminee = card->isCompleted() ? "Oui" : "Non";

            // Ã‰crire la ligne CSV
            out << nomColonne << ","
                << card->getCardId() << ","
                << titre << ","
                << description << ","
                << date << ","
                << priorite << ","
                << terminee << "\n";

            count++;
        }

        return count;
    }


// ðŸ”§ FONCTION AUXILIAIRE: Ã‰chapper les caractÃ¨res spÃ©ciaux pour CSV
QString Tableau::escaperCSV(const QString &texte)
{
    // Si le texte contient des guillemets, virgules ou retours Ã  la ligne
    if (texte.contains("\"") || texte.contains(",") || texte.contains("\n")) {
        // Doubler les guillemets et entourer de guillemets
        QString escaped = texte;
        escaped.replace("\"", "\"\"");
        return "\"" + escaped + "\"";
    }
    return texte;
}



