void Tableau::deplacerCarteVersFinished(Card* card)
{
    if (!card) {
        qDebug() << "âŒ Carte nulle";
        return;
    }

    qDebug() << "ðŸŽ¯ DÃ©placement de" << card->getTitle() << "vers FINISHED";

    // 1ï¸âƒ£ TROUVER DANS QUELLE COLONNE SE TROUVE LA CARTE
    QVBoxLayout *sourceLayout = nullptr;
    QString sourceColumnName;

    // Chercher dans TO DO
    for (int i = 0; i < ui->verticalLayoutTodo->count(); i++) {
        QLayoutItem *item = ui->verticalLayoutTodo->itemAt(i);
        if (item && item->widget() == card) {
            sourceLayout = ui->verticalLayoutTodo;
            sourceColumnName = "TO DO";
            break;
        }
    }

    // Chercher dans DOING
    if (!sourceLayout) {
        for (int i = 0; i < ui->verticalLayoutDoing->count(); i++) {
            QLayoutItem *item = ui->verticalLayoutDoing->itemAt(i);
            if (item && item->widget() == card) {
                sourceLayout = ui->verticalLayoutDoing;
                sourceColumnName = "DOING";
                break;
            }
        }
    }

    // Chercher dans les colonnes personnalisÃ©es
    if (!sourceLayout) {
        for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
            for (int i = 0; i < col.layout->count(); i++) {
                QLayoutItem *item = col.layout->itemAt(i);
                if (item && item->widget() == card) {
                    sourceLayout = col.layout;
                    sourceColumnName = col.nom;
                    break;
                }
            }
            if (sourceLayout) break;
        }
    }

    // Si la carte est dÃ©jÃ  dans FINISHED, ne rien faire
    bool isInFinished = false;
    for (int i = 0; i < ui->verticalLayoutFinished->count(); i++) {
        QLayoutItem *item = ui->verticalLayoutFinished->itemAt(i);
        if (item && item->widget() == card) {
            isInFinished = true;
            break;
        }
    }

    if (isInFinished) {
        qDebug() << "âš ï¸ Carte dÃ©jÃ  dans FINISHED";
        return;
    }

    if (!sourceLayout) {
        qDebug() << "âŒ Colonne source non trouvÃ©e";
        return;
    }

    qDebug() << "ðŸ“ Carte trouvÃ©e dans:" << sourceColumnName;

    // 2ï¸âƒ£ METTRE Ã€ JOUR LA BASE DE DONNÃ‰ES
    int carte_id = card->getCardId();

    if (carte_id != -1 && db && db->isOpen()) {
        // Trouver l'ID de la colonne FINISHED
        QSqlQuery req(*db);
        req.prepare("SELECT id_colonne FROM Colonnes WHERE id_projet = :projet_id AND nom = 'FINISHED'");
        req.bindValue(":projet_id", project_id);

        if (req.exec() && req.next()) {
            int id_colonne_finished = req.value(0).toInt();

            // Mettre Ã  jour la carte
            QSqlQuery update(*db);
            update.prepare("UPDATE Cartes SET id_colonne = :id_colonne, terminee = 1 WHERE id_carte = :id_carte");
            update.bindValue(":id_colonne", id_colonne_finished);
            update.bindValue(":id_carte", carte_id);

            if (update.exec()) {
                qDebug() << "âœ… BD mise Ã  jour: carte dÃ©placÃ©e vers FINISHED";
            } else {
                qDebug() << "âŒ Erreur BD:" << update.lastError().text();
            }
        }
    }

    // 3ï¸âƒ£ DÃ‰PLACER LA CARTE VISUELLEMENT
    sourceLayout->removeWidget(card);

    // InsÃ©rer Ã  la fin de FINISHED (avant le bouton "+")
    int insertPosition = ui->verticalLayoutFinished->count();
    ui->verticalLayoutFinished->insertWidget(insertPosition, card);

    qDebug() << "âœ… Carte dÃ©placÃ©e vers FINISHED avec succÃ¨s";
}

bool Tableau::eventFilter(QObject *watched, QEvent *event)
{
    // VÃ©rifier si c'est un Ã©vÃ©nement sur une colonne personnalisÃ©e
    QWidget *widget = qobject_cast<QWidget*>(watched);
    if (!widget) {
        return QWidget::eventFilter(watched, event);
    }

    // Trouver quelle colonne correspond Ã  ce widget
    QString columnName;
    QVBoxLayout *targetLayout = nullptr;

    for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
        if (col.widget == widget) {
            columnName = col.nom;
            targetLayout = col.layout;
            break;
        }
    }

    if (columnName.isEmpty()) {
        return QWidget::eventFilter(watched, event);
    }

    // GÃ©rer les Ã©vÃ©nements de drag & drop
    if (event->type() == QEvent::DragEnter) {
        QDragEnterEvent *dragEvent = static_cast<QDragEnterEvent*>(event);
        if (dragEvent->mimeData()->hasFormat("application/x-card")) {
            dragEvent->acceptProposedAction();
            qDebug() << "âœ… DragEnter acceptÃ© sur" << columnName;

            // Mettre en surbrillance la colonne
            widget->setStyleSheet(
                QString("#%1 {"
                "    background-color: #e3f2fd;"
                "    border: 2px solid #2196F3;"
                "    border-radius: 8px;"
                "}").arg(widget->objectName())
            );
            return true;
        }
    }
    else if (event->type() == QEvent::DragMove) {
        QDragMoveEvent *dragEvent = static_cast<QDragMoveEvent*>(event);
        if (dragEvent->mimeData()->hasFormat("application/x-card")) {
            dragEvent->acceptProposedAction();
            return true;
        }
    }
    else if (event->type() == QEvent::Drop) {
        QDropEvent *dropEvent = static_cast<QDropEvent*>(event);
        if (dropEvent->mimeData()->hasFormat("application/x-card")) {
            qDebug() << "ðŸ“¦ Drop sur colonne personnalisÃ©e:" << columnName;
            handleDropInColumn(dropEvent, targetLayout, columnName);

            // Restaurer le style normal
            widget->setStyleSheet(
                QString("#%1 {"
                "    background-color: #f5f7fa;"
                "    border: 2px solid #d1d8e0;"
                "    border-radius: 8px;"
                "}").arg(widget->objectName())
            );
            return true;
        }
    }
    else if (event->type() == QEvent::DragLeave) {
        // Restaurer le style normal quand on quitte la colonne
        widget->setStyleSheet(
            QString("#%1 {"
            "    background-color: #f5f7fa;"
            "    border: 2px solid #d1d8e0;"
            "    border-radius: 8px;"
            "}").arg(widget->objectName())
        );
        qDebug() << "ðŸš« DragLeave de" << columnName;
    }

    return QWidget::eventFilter(watched, event);
}

