void Tableau::onSearchTextChanged(const QString &text)
{
    // Activer/désactiver le bouton Effacer
    m_clearSearchButton->setEnabled(!text.isEmpty());

    // Recherche en temps réel avec anti-rebond
    static QTimer searchTimer;
    searchTimer.setSingleShot(true);

    disconnect(&searchTimer, &QTimer::timeout, nullptr, nullptr);
    connect(&searchTimer, &QTimer::timeout, [this, text]() {
        if (m_searchEdit && m_searchEdit->text() == text) {
            filterAllCards(text);
        }
    });

    searchTimer.start(300); // 300ms de délai
}

