QList<Card*> Tableau::getAllCardsInProject()
{
    QList<Card*> allCards;

    // Fonction pour extraire les cartes d'un layout
    auto extractCardsFromLayout = [](QVBoxLayout *layout, QList<Card*> &cardList) {
        if (!layout) return;
        for (int i = 0; i < layout->count(); i++) {
            QLayoutItem *item = layout->itemAt(i);
            if (item && item->widget()) {
                if (Card *card = qobject_cast<Card*>(item->widget())) {
                    cardList.append(card);
                }
            }
        }
    };

    // Cartes des colonnes fixes
    extractCardsFromLayout(ui->verticalLayoutTodo, allCards);
    extractCardsFromLayout(ui->verticalLayoutDoing, allCards);
    extractCardsFromLayout(ui->verticalLayoutFinished, allCards);

    // Cartes des colonnes personnalisées
    for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
        extractCardsFromLayout(col.layout, allCards);
    }

    return allCards;
}

bool Tableau::cardMatchesSearch(Card *card, const QString &searchText)
{
    if (searchText.isEmpty()) return true;

    QString searchLower = searchText.toLower();

    // Rechercher dans le titre
    if (card->getTitle().toLower().contains(searchLower)) {
        return true;
    }

    // Rechercher dans la description
    if (card->getDescription().toLower().contains(searchLower)) {
        return true;
    }

    // Rechercher dans les tags
    QStringList tags = card->getTags();
    for (const QString &tag : tags) {
        if (tag.toLower().contains(searchLower)) {
            return true;
        }
    }

    // Rechercher dans la priorité
    if (card->getPriority().toLower().contains(searchLower)) {
        return true;
    }

    return false;
}

void Tableau::filterAllCards(const QString &searchText)
{
    // Récupérer toutes les cartes
    QList<Card*> allCards = getAllCardsInProject();
    int visibleCount = 0;
    int totalCount = allCards.size();

    // Filtrer les cartes
    for (Card *card : allCards) {
        bool matches = cardMatchesSearch(card, searchText);
        card->setVisible(matches);

        if (matches) {
            visibleCount++;
        }
    }

    // Mettre à jour le label des résultats
    if (!searchText.isEmpty()) {
        if (visibleCount == 0) {
            m_searchResultLabel->setText(QString("❌ Aucun résultat pour \"%1\"").arg(searchText));
            m_searchResultLabel->setStyleSheet("color: #e53e3e; font-style: italic; font-size: 12px;");
        } else {
            m_searchResultLabel->setText(QString("🔍 %1/%2 cartes trouvées").arg(visibleCount).arg(totalCount));
            m_searchResultLabel->setStyleSheet("color: #3182ce; font-style: italic; font-size: 12px;");
        }
    } else {
        m_searchResultLabel->clear();
    }

    qDebug() << "🔍 Recherche terminée :" << visibleCount << "/" << totalCount << "cartes";
}

