// tableau.cpp - AJOUTER CETTE MÉTHODE
void Tableau::clearAllCards()
{
    if (!db || !db->isOpen() || project_id == -1) {
        qDebug() << "❌ Base de données non disponible";
        QMessageBox::critical(this, "Erreur", "Impossible de se connecter à la base de données");
        return;
    }

    qDebug() << "🧹 Début de suppression de toutes les cartes du projet" << project_id;

    int deletedCount = 0;

    // 1. SUPPRIMER TOUTES LES CARTES DE LA BASE DE DONNÉES
    QSqlQuery deleteQuery(*db);
    deleteQuery.prepare(
        "DELETE FROM Cartes "
        "WHERE id_colonne IN ("
        "   SELECT id_colonne FROM Colonnes WHERE id_projet = :projet_id"
        ")"
    );
    deleteQuery.bindValue(":projet_id", project_id);

    if (deleteQuery.exec()) {
        deletedCount = deleteQuery.numRowsAffected();
        qDebug() << "🗑️" << deletedCount << "cartes supprimées de la base de données";
    } else {
        qDebug() << "❌ Erreur BD:" << deleteQuery.lastError().text();
        QMessageBox::critical(this, "Erreur BD",
            "Erreur lors de la suppression:\n" + deleteQuery.lastError().text());
        return;
    }

    // 2. SUPPRIMER TOUTES LES CARTES DE L'INTERFACE

    // Fonction pour supprimer les cartes d'un layout
    auto clearLayout = [](QVBoxLayout* layout) {
        if (!layout) return 0;

        int count = 0;
        // Parcourir à l'envers pour éviter les problèmes d'index
        for (int i = layout->count() - 1; i >= 0; i--) {
            QLayoutItem* item = layout->itemAt(i);
            if (item && item->widget()) {
                if (qobject_cast<Card*>(item->widget())) {
                    item->widget()->deleteLater();
                    delete item;
                    count++;
                }
            }
        }
        return count;
    };

    int uiDeleted = 0;

    uiDeleted += clearLayout(ui->verticalLayoutTodo);
    uiDeleted += clearLayout(ui->verticalLayoutDoing);
    uiDeleted += clearLayout(ui->verticalLayoutFinished);

    for (const ColonnePersonnalisee &col : colonnesPersonnalisees) {
        if (col.layout) {
            uiDeleted += clearLayout(col.layout);
        }
    }

    qDebug() << "🧹" << uiDeleted << "cartes supprimées de l'interface";


    QString message;
    if (deletedCount > 0) {
        message = QString(" %1 tâche(s) supprimée(s) avec succès").arg(deletedCount);

        QMessageBox::information(this, "Succès", message);

        // Petit effet visuel pour confirmer
        QTimer::singleShot(100, [this]() {
            // Clignoter brièvement le bouton en vert
            QString originalStyle = ui->pushButton->styleSheet();
            ui->pushButton->setStyleSheet(
                "QPushButton {"
                "   background-color: #2ecc71;"
                "   color: white;"
                "   border: 2px solid #27ae60;"
                "   border-radius: 10px;"
                "}"
            );

            QTimer::singleShot(300, [this, originalStyle]() {
                ui->pushButton->setStyleSheet(originalStyle);
            });
        });

    } else {
        QMessageBox::information(this, "Information",
            "Aucune tâche à supprimer.");
    }

    qDebug() << "✅ Suppression terminée";
}

