void TagsWidget::onAddTagClicked()
{
    QString tag = tagInput->text().trimmed();

    if (tag.isEmpty()) {
        return;
    }

    // Éviter les doublons
    if (selectedTags.contains(tag)) {
        tagInput->clear();
        return;
    }

    // Ajouter le tag
    QString color = getRandomColor();
    selectedTags[tag] = color;
    addTagToDisplay(tag, color);

    tagInput->clear();

    emit tagsChanged(selectedTags.keys());
}

void TagsWidget::addTagToDisplay(const QString &tag, const QString &color)
{
    QFrame *tagFrame = new QFrame();
    tagFrame->setObjectName("tag_" + tag);
    tagFrame->setStyleSheet(
        QString("QFrame {"
        "   background-color: %1;"
        "   border-radius: 12px;"
        "   padding: 6px 12px;"
        "}").arg(color)
    );

    QHBoxLayout *tagLayout = new QHBoxLayout(tagFrame);
    tagLayout->setSpacing(8);
    tagLayout->setContentsMargins(8, 4, 8, 4);

    QLabel *tagLabel = new QLabel(tag);
    tagLabel->setStyleSheet(
        "color: white;"
        "font-size: 13px;"
        "font-weight: bold;"
        "background: transparent;"
    );

    QPushButton *removeBtn = new QPushButton("×");
    removeBtn->setFixedSize(20, 20);
    removeBtn->setCursor(Qt::PointingHandCursor);
    removeBtn->setStyleSheet(
        "QPushButton {"
        "   background-color: rgba(255, 255, 255, 0.3);"
        "   color: white;"
        "   border: none;"
        "   border-radius: 10px;"
        "   font-size: 16px;"
        "   font-weight: bold;"
        "}"
        "QPushButton:hover {"
        "   background-color: rgba(255, 255, 255, 0.5);"
        "}"
    );

    connect(removeBtn, &QPushButton::clicked, [this, tag]() {
        onTagRemoved(tag);
    });

    tagLayout->addWidget(tagLabel);
    tagLayout->addWidget(removeBtn);

    tagsLayout->addWidget(tagFrame);
}

void TagsWidget::onTagRemoved(const QString &tag)
{
    selectedTags.remove(tag);
    removeTagFromDisplay(tag);
    emit tagsChanged(selectedTags.keys());
}

void TagsWidget::removeTagFromDisplay(const QString &tag)
{
    QFrame *tagFrame = tagsContainer->findChild<QFrame*>("tag_" + tag);
    if (tagFrame) {
        tagFrame->deleteLater();
    }
}

QString TagsWidget::getRandomColor()
{
    int index = QRandomGenerator::global()->bounded(availableColors.size());
    return availableColors[index];
}

QStringList TagsWidget::getSelectedTags() const
{
    return selectedTags.keys();
}

void TagsWidget::setSelectedTags(const QStringList &tags)
{
    clearTags();

    for (const QString &tag : tags) {
        QString color = getRandomColor();
        selectedTags[tag] = color;
        addTagToDisplay(tag, color);
    }
}

void TagsWidget::clearTags()
{
    selectedTags.clear();

    // Supprimer tous les widgets de tags
    QList<QFrame*> frames = tagsContainer->findChildren<QFrame*>();
    for (QFrame *frame : frames) {
        frame->deleteLater();
    }
}

