void TimeWidget::onTimeChanged()
{
    updateProgress();
    emit timeChanged(estimatedSpinBox->value(), spentSpinBox->value());
}

void TimeWidget::updateProgress()
{
    int estimated = estimatedSpinBox->value();
    int spent = spentSpinBox->value();

    if (estimated == 0) {
        progressBar->setValue(0);
        percentLabel->setText("Progression : 0%");
        progressBar->setStyleSheet(
            "QProgressBar {"
            "   border: 2px solid #e0e0e0;"
            "   border-radius: 8px;"
            "   background-color: white;"
            "}"
            "QProgressBar::chunk {"
            "   background: qlineargradient(x1:0, y1:0, x2:1, y2:0, "
            "       stop:0 #667eea, stop:1 #764ba2);"
            "   border-radius: 6px;"
            "}"
        );
        return;
    }

    int percentage = (spent * 100) / estimated;
    if (percentage > 100) percentage = 100;

    progressBar->setValue(percentage);
    percentLabel->setText(QString("Progression : %1%").arg(percentage));

    // Changer la couleur selon le pourcentage
    QString color;
    if (percentage >= 100) {
        color = "stop:0 #e74c3c, stop:1 #c0392b";  // Rouge (dépassé)
    } else if (percentage >= 80) {
        color = "stop:0 #f39c12, stop:1 #e67e22";  // Orange (attention)
    } else if (percentage >= 50) {
        color = "stop:0 #3498db, stop:1 #2980b9";  // Bleu
    } else {
        color = "stop:0 #2ecc71, stop:1 #27ae60";  // Vert (bon)
    }

    progressBar->setStyleSheet(
        QString("QProgressBar {"
        "   border: 2px solid #e0e0e0;"
        "   border-radius: 8px;"
        "   background-color: white;"
        "}"
        "QProgressBar::chunk {"
        "   background: qlineargradient(x1:0, y1:0, x2:1, y2:0, %1);"
        "   border-radius: 6px;"
