TranslationManager::~TranslationManager() {
    m_registeredWidgets.clear();
}

void TranslationManager::toggleLanguage() {
    m_isEnglish = !m_isEnglish;
    translateAllWidgets();
    emit languageChanged();
}

void TranslationManager::registerWidget(QWidget* widget) {
    if (widget && !m_registeredWidgets.contains(widget)) {
        m_registeredWidgets.append(widget);
    }
}

void TranslationManager::unregisterWidget(QWidget* widget) {
    m_registeredWidgets.removeAll(widget);
}

void TranslationManager::translateAllWidgets() {
    for (QWidget* widget : m_registeredWidgets) {
        if (widget) {
            translateWidget(widget);
        }
    }

    // Traduire aussi les fenêtres modales qui ne sont pas enregistrées
    for (QWidget* widget : QApplication::topLevelWidgets()) {
        if (!m_registeredWidgets.contains(widget)) {
            translateWidget(widget);
        }
    }
}

QString TranslationManager::translate(const QString& text) {
    if (text.isEmpty()) return text;

    if (m_isEnglish) {
        // Traduire du français vers l'anglais
        return m_frToEn.value(text, text);
    } else {
        // Traduire de l'anglais vers le français
        return m_enToFr.value(text, text);
    }
}

QString TranslationManager::autoDetectAndTranslate(const QString& text) {
    if (text.isEmpty()) return text;

    // Vérifier si le texte est en français (contient des accents ou mots français courants)
    bool isFrench = text.contains(QRegExp("[éèêëàâäîïôöùûüçÉÈÊËÀÂÄÎÏÔÖÙÛÜÇ]")) ||
                   text.contains(" de ") || text.contains(" le ") || text.contains(" la ") ||
                   text.contains(" et ") || text.contains(" ou ") || text.contains(" dans ");

    if (m_isEnglish && isFrench) {
        // Traduire français -> anglais
        return m_frToEn.value(text, text);
    } else if (!m_isEnglish && !isFrench && text != text.toUpper()) {
        // Traduire anglais -> français (sauf les acronymes comme TO DO, DOING, etc.)
        QString translated = m_enToFr.value(text, text);
        if (translated != text) {
            return translated;
        }
    }

    return text;
}

void TranslationManager::translateWidget(QWidget* widget) {
    if (!widget) return;

    autoTranslateWidget(widget);
}

void TranslationManager::autoTranslateWidget(QWidget* widget) {
    if (!widget) return;

    // Traduire le widget lui-même
    QString widgetText = widget->property("text").toString();
    if (!widgetText.isEmpty()) {
        QString translated = autoDetectAndTranslate(widgetText);
        if (translated != widgetText) {
            widget->setProperty("text", translated);
        }
    }

    QString toolTip = widget->toolTip();
    if (!toolTip.isEmpty()) {
        QString translated = autoDetectAndTranslate(toolTip);
        if (translated != toolTip) {
            widget->setToolTip(translated);
        }
    }

    QString statusTip = widget->statusTip();
    if (!statusTip.isEmpty()) {
        QString translated = autoDetectAndTranslate(statusTip);
        if (translated != statusTip) {
            widget->setStatusTip(translated);
        }
    }

    QString windowTitle = widget->windowTitle();
    if (!windowTitle.isEmpty()) {
        QString translated = autoDetectAndTranslate(windowTitle);
        if (translated != windowTitle) {
            widget->setWindowTitle(translated);
        }
    }

    // Traduire les types spécifiques de widgets
    if (auto btn = qobject_cast<QPushButton*>(widget)) {
        QString text = btn->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                btn->setText(translated);
            }
        }
    }
    else if (auto lbl = qobject_cast<QLabel*>(widget)) {
        QString text = lbl->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                lbl->setText(translated);
            }
        }
    }
    else if (auto chk = qobject_cast<QCheckBox*>(widget)) {
        QString text = chk->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                chk->setText(translated);
            }
        }
    }
    else if (auto rbtn = qobject_cast<QRadioButton*>(widget)) {
        QString text = rbtn->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                rbtn->setText(translated);
            }
        }
    }
    else if (auto grp = qobject_cast<QGroupBox*>(widget)) {
        QString text = grp->title();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                grp->setTitle(translated);
            }
        }
    }
    else if (auto tab = qobject_cast<QTabWidget*>(widget)) {
        for (int i = 0; i < tab->count(); ++i) {
            QString text = tab->tabText(i);
            if (!text.isEmpty()) {
                QString translated = autoDetectAndTranslate(text);
                if (translated != text) {
                    tab->setTabText(i, translated);
                }
            }
        }
    }
    else if (auto menu = qobject_cast<QMenu*>(widget)) {
        QString text = menu->title();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                menu->setTitle(translated);
            }
        }
    }
    else if (auto action = qobject_cast<QAction*>(widget)) {
        QString text = action->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                action->setText(translated);
            }
        }
    }
    else if (auto lineEdit = qobject_cast<QLineEdit*>(widget)) {
        QString placeholder = lineEdit->placeholderText();
        if (!placeholder.isEmpty()) {
            QString translated = autoDetectAndTranslate(placeholder);
            if (translated != placeholder) {
                lineEdit->setPlaceholderText(translated);
            }
        }
    }
    else if (auto combo = qobject_cast<QComboBox*>(widget)) {
        for (int i = 0; i < combo->count(); ++i) {
            QString text = combo->itemText(i);
            if (!text.isEmpty()) {
                QString translated = autoDetectAndTranslate(text);
                if (translated != text) {
                    combo->setItemText(i, translated);
                }
            }
        }
    }
    else if (auto msgBox = qobject_cast<QMessageBox*>(widget)) {
        QString text = msgBox->text();
        if (!text.isEmpty()) {
            QString translated = autoDetectAndTranslate(text);
            if (translated != text) {
                msgBox->setText(translated);
            }
        }

        QString informative = msgBox->informativeText();
        if (!informative.isEmpty()) {
            QString translated = autoDetectAndTranslate(informative);
            if (translated != informative) {
                msgBox->setInformativeText(translated);
            }
        }
    }

    // Traduire les enfants récursivement
    QObjectList children = widget->children();
    for (QObject* child : children) {
        if (auto childWidget = qobject_cast<QWidget*>(child)) {
            autoTranslateWidget(childWidget);
        }
    }
}

